package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal
var WsWrapTotal decimal.Decimal
var WsSafeTotal decimal.Decimal
var WsOverflows int64
var WsCount int64
var WsHalf decimal.Decimal
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtRec AmtRec
var amtFile *os.File
var scanner *bufio.Scanner

func pow10Int(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func isSizeError(val decimal.Decimal, pInt int, pScale int32) bool {
	truncated := val.Truncate(pScale)
	intPart := truncated.Truncate(0).Abs()
	limit := decimal.NewFromInt(pow10Int(pInt))
	return intPart.Cmp(limit) >= 0
}

func storeDecimal(val decimal.Decimal, pInt int, pScale int32) decimal.Decimal {
	truncated := val.Truncate(pScale)
	scaled := truncated.Shift(pScale)
	isNeg := scaled.Sign() < 0
	if isNeg {
		scaled = scaled.Abs()
	}
	scaledInt := scaled.IntPart()
	totalDigits := pInt + int(pScale)
	pow10Total := pow10Int(totalDigits)
	wrappedInt := scaledInt % pow10Total
	if isNeg {
		wrappedInt = -wrappedInt
	}
	return decimal.New(wrappedInt, -pScale)
}

func moveDecimal(src decimal.Decimal, tgtInt int, tgtScale int32) decimal.Decimal {
	return storeDecimal(src, tgtInt, tgtScale)
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		decPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decDigits++
		}
	}
	truncated := val.Truncate(int32(decDigits))
	isNeg := truncated.Sign() < 0
	absVal := truncated.Abs()
	scaled := absVal.Shift(int32(decDigits))
	scaledInt := scaled.IntPart()
	totalDigits := intDigits + decDigits
	pow10Total := pow10Int(totalDigits)
	wrappedInt := scaledInt % pow10Total
	pow10Dec := pow10Int(decDigits)
	var intPart, fracPart int64
	if decDigits > 0 {
		intPart = wrappedInt / pow10Dec
		fracPart = wrappedInt % pow10Dec
	} else {
		intPart = wrappedInt
		fracPart = 0
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := ""
	if decDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", decDigits, fracPart)
	}
	outInt := make([]byte, len(intPic))
	digitIdx := 0
	stillSup := true
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if c == 'Z' {
				if d == '0' && stillSup {
					outInt[i] = ' '
				} else {
					outInt[i] = d
					stillSup = false
				}
			} else {
				outInt[i] = d
				stillSup = false
			}
		} else if c == ',' {
			if stillSup {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else {
			outInt[i] = byte(c)
		}
	}
	var result string
	if decDigits > 0 {
		result = string(outInt) + "." + fracStr
	} else {
		result = string(outInt)
	}
	if isNeg && len(result) > 0 {
		result = "-" + result[1:]
	}
	return result
}

func inputDone() bool {
	return WsEofFlag == "Y"
}

func openAmtFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "error opening input.dat: %v\n", err)
		os.Exit(1)
	}
	amtFile = f
	scanner = bufio.NewScanner(f)
}

func closeAmtFile() {
	if amtFile != nil {
		amtFile.Close()
	}
}

func mainPara() {
	openAmtFile()
	readPara()
	for !inputDone() {
		processPara()
	}
	closeAmtFile()
	summaryPara()
}

func readPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 11 {
			line += strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		arAcct := line[0:4]
		arAmtStr := line[4:11]
		clean := strings.ReplaceAll(arAmtStr, " ", "0")
		var n int64
		for _, ch := range clean {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			} else {
				n = n * 10
			}
		}
		amtRec.ArAcct = arAcct
		amtRec.ArAmt = decimal.New(n, -2)
		WsEofFlag = "N"
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "error reading input.dat: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func processPara() {
	sumBig := WsBigTotal.Add(amtRec.ArAmt)
	WsBigTotal = storeDecimal(sumBig, 7, 2)
	WsWrapTotal = moveDecimal(WsBigTotal, 5, 2)
	tentativeSafe := WsSafeTotal.Add(amtRec.ArAmt)
	if isSizeError(tentativeSafe, 5, 2) {
		overflowPara()
	} else {
		WsSafeTotal = storeDecimal(tentativeSafe, 5, 2)
	}
	WsCount = (WsCount + 1) % pow10Int(2)
	halfExact := amtRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	halfTrunc := halfExact.Truncate(1)
	WsHalf = storeDecimal(halfTrunc, 5, 1)
	WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	readPara()
}

func summaryPara() {
	countStr := fmt.Sprintf("%02d", WsCount%pow10Int(2))
	overStr := fmt.Sprintf("%02d", WsOverflows%pow10Int(2))
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("OVERFLOWS: %s\n", overStr)
}

func overflowPara() {
	WsOverflows = (WsOverflows + 1) % pow10Int(2)
}

func main() {
	WsEofFlag = "N"
	WsBigTotal = decimal.NewFromInt(0)
	WsWrapTotal = decimal.NewFromInt(0)
	WsSafeTotal = decimal.NewFromInt(0)
	WsOverflows = 0
	WsCount = 0
	WsHalf = decimal.NewFromInt(0)
	mainPara()
}
